package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.SubLine;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for SubLine#intersection.
 */
public class SubLine_intersection_TriageGen4Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_IncludeEndPoints_Inside() throws Exception {
        // Line 1: x-axis from -10 to 10
        SubLine subLine1 = new SubLine(new Vector3D(-10, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from -10 to 10
        SubLine subLine2 = new SubLine(new Vector3D(0, -10, 0), new Vector3D(0, 10, 0));

        // Intersection at (0,0,0) which is INSIDE both
        Vector3D result = subLine1.intersection(subLine2, true);
        assertVectorEquals(new Vector3D(0, 0, 0), result);
    }

    @Test
    public void testIntersection_IncludeEndPoints_AtBoundary() throws Exception {
        // Line 1: x-axis from 0 to 10
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from 0 to 10
        SubLine subLine2 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(0, 10, 0));

        // Intersection at (0,0,0) which is a boundary point (Location.BOUNDARY)
        // With includeEndPoints = true, it should return the point
        Vector3D result = subLine1.intersection(subLine2, true);
        assertVectorEquals(new Vector3D(0, 0, 0), result);
    }

    @Test
    public void testIntersection_IncludeEndPoints_Outside() throws Exception {
        // Line 1: x-axis from 0 to 5
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(5, 0, 0));
        // Line 2: y-axis from 5 to 10
        SubLine subLine2 = new SubLine(new Vector3D(0, 5, 0), new Vector3D(0, 10, 0));

        // Infinite lines intersect at (0,0,0), but (0,0,0) is OUTSIDE subLine2
        Vector3D result = subLine1.intersection(subLine2, true);
        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_Inside() throws Exception {
        // Line 1: x-axis from -10 to 10
        SubLine subLine1 = new SubLine(new Vector3D(-10, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from -10 to 10
        SubLine subLine2 = new SubLine(new Vector3D(0, -10, 0), new Vector3D(0, 10, 0));

        // Intersection at (0,0,0) which is INSIDE both
        // With includeEndPoints = false, it should return the point
        Vector3D result = subLine1.intersection(subLine2, false);
        assertVectorEquals(new Vector3D(0, 0, 0), result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_AtBoundary() throws Exception {
        // Line 1: x-axis from 0 to 10
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from 0 to 10
        SubLine subLine2 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(0, 10, 0));

        // Intersection at (0,0,0) which is a boundary point
        // With includeEndPoints = false, it should return null because boundary != INSIDE
        Vector3D result = subLine1.intersection(subLine2, false);
        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_Outside() throws Exception {
        // Line 1: x-axis from 0 to 5
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(5, 0, 0));
        // Line 2: y-axis from 5 to 10
        SubLine subLine2 = new SubLine(new Vector3D(0, 5, 0), new Vector3D(0, 10, 0));

        // Intersection at (0,0,0) is OUTSIDE
        Vector3D result = subLine1.intersection(subLine2, false);
        assertNull(result);
    }

    private void assertVectorEquals(Vector3D expected, Vector3D actual) {
        assertEquals("X coordinate mismatch", expected.getX(), actual.getX(), EPSILON);
        assertEquals("Y coordinate mismatch", expected.getY(), actual.getY(), EPSILON);
        assertEquals("Z coordinate mismatch", expected.getZ(), actual.getZ(), EPSILON);
    }
}
